class WebSocketHandler{constructor(){this.socket=null,this.connected=!1,this.reconnectAttempts=0,this.maxReconnectAttempts=5,this.reconnectInterval=3e3,this.messageHandlers={},this.connectionHandlers={onOpen:[],onClose:[],onError:[]}}connect(e=CONFIG.WS_URL){return new Promise(((t,n)=>{try{console.log(`正在连接到WebSocket服务器: ${e}`),this.socket=new WebSocket(e),this.socket.onopen=e=>{console.log("WebSocket连接已建立"),this.connected=!0,this.reconnectAttempts=0,this.connectionHandlers.onOpen.forEach((t=>{try{t(e)}catch(e){console.error("执行onOpen处理器时出错:",e)}})),t(this.socket)},this.socket.onclose=e=>{console.log(`WebSocket连接已关闭: ${e.code} ${e.reason}`),this.connected=!1,this.connectionHandlers.onClose.forEach((t=>{try{t(e)}catch(e){console.error("执行onClose处理器时出错:",e)}})),this._attemptReconnect()},this.socket.onerror=e=>{console.error("WebSocket连接错误:",e),this.connectionHandlers.onError.forEach((t=>{try{t(e)}catch(e){console.error("执行onError处理器时出错:",e)}})),n(new Error("WebSocket连接错误"))},this.socket.onmessage=e=>{try{const t=JSON.parse(e.data);console.log("收到WebSocket消息:",t),this._handleMessage(t)}catch(e){console.error("处理WebSocket消息时出错:",e)}}}catch(e){console.error("创建WebSocket连接时出错:",e),n(e)}}))}_attemptReconnect(){this.reconnectAttempts<this.maxReconnectAttempts?(this.reconnectAttempts++,console.log(`尝试重新连接 (${this.reconnectAttempts}/${this.maxReconnectAttempts})...`),setTimeout((()=>{this.connect().catch((e=>{console.error("重新连接失败:",e)}))}),this.reconnectInterval)):console.error("达到最大重连次数，放弃重连")}_handleMessage(e){const{type:t}=e;t&&this.messageHandlers[t]?this.messageHandlers[t].forEach((n=>{try{n(e)}catch(e){console.error(`执行消息处理器(${t})时出错:`,e)}})):console.warn(`未找到消息类型(${t})的处理器`)}send(e){if(!this.connected||!this.socket)return console.error("WebSocket未连接，无法发送消息"),!1;try{const t=JSON.stringify(e);return this.socket.send(t),console.log("已发送WebSocket消息:",e),!0}catch(e){return console.error("发送WebSocket消息时出错:",e),!1}}sendChatMessage(e,t=null){const n={type:CONFIG.MESSAGE_TYPES.CHAT,content:e,timestamp:(new Date).toISOString()};return t&&(n.receiver=t),this.send(n)}sendCallRequest(e){return this.send({type:CONFIG.MESSAGE_TYPES.CALL_REQUEST,targetUserId:e,timestamp:(new Date).toISOString()})}sendCallResponse(e,t){return this.send({type:CONFIG.MESSAGE_TYPES.CALL_RESPONSE,targetUserId:e,accepted:t,timestamp:(new Date).toISOString()})}sendOffer(e,t){return this.send({type:CONFIG.MESSAGE_TYPES.OFFER,targetUserId:e,offer:t,timestamp:(new Date).toISOString()})}sendAnswer(e,t){return this.send({type:CONFIG.MESSAGE_TYPES.ANSWER,targetUserId:e,answer:t,timestamp:(new Date).toISOString()})}sendIceCandidate(e,t){return this.send({type:CONFIG.MESSAGE_TYPES.ICE_CANDIDATE,targetUserId:e,candidate:t,timestamp:(new Date).toISOString()})}addMessageHandler(e,t){this.messageHandlers[e]||(this.messageHandlers[e]=[]),this.messageHandlers[e].push(t),console.log(`已添加消息处理器: ${e}`)}addConnectionHandler(e,t){const n=`on${e.charAt(0).toUpperCase()+e.slice(1)}`;this.connectionHandlers[n]?(this.connectionHandlers[n].push(t),console.log(`已添加连接事件处理器: ${n}`)):console.warn(`未知的连接事件类型: ${e}`)}disconnect(){this.socket&&this.connected&&(console.log("正在关闭WebSocket连接..."),this.socket.close(),this.socket=null,this.connected=!1)}}